document.addEventListener('click', event => {
 const link = event.target.closest?.('a[href]');
 if (!link) return;
 const url = new URL(link.href, location.href);
 let method;
 if (url.protocol === 'tel:') {
  track('contact_phone_click');
  method = 'telephone';
 } else if (url.protocol === 'mailto:') {
  track('contact_email_click');
  method = 'email';
 } else if (url.protocol === 'https:' && url.hostname === 'wa.me' && url.pathname === '/447383660882') {
  track('contact_whatsapp_click');
  method = 'whatsapp';
 }
 const quotePage = location.pathname === '/booking.html';
 const quoteSection = link.closest('main #contact, main .lt-enquiry-main');
 if (method && (quotePage || quoteSection) && read() === true && loaded && !window['ga-disable-'+id]) {
  gtag('event','quote_enquiry_start',{contact_method:method});
 }
});
